import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.2Gs1zKBA.js";const _=JSON.parse('{"title":"模型与控制生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/index.md","filePath":"concepts/index.md","lastUpdated":1792735328000}'),c={name:"concepts/index.md"};function l(i,e,r,n,s,h){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="模型与控制生命周期" tabindex="-1">模型与控制生命周期 <a class="header-anchor" href="#模型与控制生命周期" aria-label="Permalink to &quot;模型与控制生命周期&quot;">​</a></h1><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型名</th><th>含义</th></tr></thead><tbody><tr><td><code>A1L</code></td><td>左机械臂</td></tr><tr><td><code>A1R</code></td><td>右机械臂</td></tr></tbody></table><p>角度使用弧度，角速度使用 <code>rad/s</code>，位置使用米，力和力矩分别使用牛顿和牛顿米。</p><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h2><ol><li>创建 <code>Arm</code> 并选择唯一后端：<code>channel</code>、<code>backend</code> 或 <code>can_bus</code> 三选一。</li><li>调用 <code>enable()</code> 进入可控状态。</li><li>发送运动或状态查询指令。</li><li>使用 <code>stop()</code> 中断运动，必要时切断电源。</li><li>仅在机械臂已得到可靠支撑时调用 <code>disable()</code>。</li><li><code>close()</code> 关闭通信资源，默认不失能。</li></ol><div class="warning custom-block"><p class="custom-block-title">术语区别</p><ul><li><strong>停止运动</strong>：<code>stop()</code>，尽量减速至静止并保持控制。</li><li><strong>失能</strong>：<code>disable()</code>，电机不再提供维持姿态所需的力矩，机械臂可能下落。</li><li><strong>紧急停止</strong>：<code>emergency_stop()</code> 立即失能所有电机（之后需 <code>enable()</code> 恢复），不应与普通停止混用。</li></ul></div><h2 id="上下文管理器" tabindex="-1">上下文管理器 <a class="header-anchor" href="#上下文管理器" aria-label="Permalink to &quot;上下文管理器&quot;">​</a></h2><p><code>with Arm(...)</code> 会调用 <code>enable()</code>，退出时关闭通信；它不会默认失能。这一行为用于避免带重力负载的机械臂突然下落。</p>',9)])])}const b=o(c,[["render",l]]);export{_ as __pageData,b as default};
